package com.ruoyi.warehouse.inbound;
import org.springframework.jdbc.core.JdbcTemplate;
final class AsnCustodySchema {
    static void create(JdbcTemplate jdbc){
        jdbc.execute("CREATE TABLE wh_asn_late_link(child_asn VARCHAR(64) PRIMARY KEY REFERENCES wh_record(id),parent_asn VARCHAR(64) REFERENCES wh_record(id),admin_policy VARCHAR(16),sku_policy VARCHAR(16),reason VARCHAR(500),actor_id BIGINT,created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),evidence_json VARCHAR(1000000))");
        jdbc.execute("CREATE TABLE wh_asn_custody(id VARCHAR(64) PRIMARY KEY,asn_id VARCHAR(64) REFERENCES wh_record(id),product_id VARCHAR(64) REFERENCES wh_record(id),location_id VARCHAR(64) REFERENCES wh_record(id),quantity BIGINT CHECK(quantity>0 AND quantity<=10000000),disposed_quantity BIGINT DEFAULT 0 CHECK(disposed_quantity>=0 AND disposed_quantity<=quantity),accepted_quantity BIGINT DEFAULT 0 CHECK(accepted_quantity>=0 AND accepted_quantity<=disposed_quantity),returned_quantity BIGINT DEFAULT 0 CHECK(returned_quantity>=0 AND returned_quantity+accepted_quantity<=disposed_quantity),approved_extra BIGINT DEFAULT 0 CHECK(approved_extra>=0 AND approved_extra<=quantity),layer_id VARCHAR(64) UNIQUE REFERENCES wh_stock_layer(id),batch_number VARCHAR(191) DEFAULT '',serial_number VARCHAR(191) DEFAULT '',expiry_date VARCHAR(10) DEFAULT '',inspection VARCHAR(16) DEFAULT 'PENDING' CHECK(inspection IN('PENDING','PASS','FAIL')),reason VARCHAR(500),received_by BIGINT,received_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6))");
        jdbc.execute("CREATE TABLE wh_asn_return_approval(id VARCHAR(64) PRIMARY KEY,custody_id VARCHAR(64) REFERENCES wh_asn_custody(id),quantity BIGINT CHECK(quantity>0),handed_quantity BIGINT DEFAULT 0 CHECK(handed_quantity>=0),cancelled_quantity BIGINT DEFAULT 0 CHECK(cancelled_quantity>=0 AND handed_quantity+cancelled_quantity<=quantity),recipient VARCHAR(200),destination VARCHAR(1000),reference VARCHAR(200),reason VARCHAR(500),actor_id BIGINT,created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),evidence_json VARCHAR(1000000))");
        jdbc.execute("CREATE TABLE wh_asn_custody_event(id VARCHAR(64) PRIMARY KEY,custody_id VARCHAR(64) REFERENCES wh_asn_custody(id),action_name VARCHAR(24) CHECK(action_name IN('stage','inspect','approveOverage','putaway','scrap','approveReturn','cancelReturnApproval','returnSupplier')),quantity BIGINT DEFAULT 0 CHECK(quantity>=0),location_id VARCHAR(64) REFERENCES wh_record(id),reason VARCHAR(500),actor_id BIGINT,created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),result_json VARCHAR(1000000),return_approval_id VARCHAR(64) REFERENCES wh_asn_return_approval(id),handover_reference VARCHAR(200) DEFAULT '')");
        UnidentifiedSchema.createActions(jdbc);
    }
}
